try{$pdo=business_db();product_step11_ensure($pdo);$ctx=product_org_context($pdo);$orgId=(int)$ctx['organization_id'];$data=product_step11_seed_data();$market=product_step11_market($pdo,$orgId);$marketId=(int)$market['id'];product_step11_apply_seed($pdo);
