$metrics['categories']=$scalar("SELECT COUNT(*) FROM product_categories WHERE organization_id=? AND status='active'",[$orgId]);$metrics['products']=$scalar("SELECT COUNT(*) FROM products WHERE organization_id=?",[$orgId]);$metrics['listings']=$scalar("SELECT COUNT(*) FROM product_market_listings WHERE organization_id=? AND market_id=?",[$orgId,$marketId]);$metrics['prices']=$scalar("SELECT COUNT(*) FROM product_price_versions pv JOIN product_market_listings l ON l.id=pv.listing_id WHERE pv.organization_id=? AND l.market_id=? AND pv.effective_from=?",[$orgId,$marketId,PRODUCT_STEP11_EFFECTIVE_DATE]);$metrics['tiers']=$scalar("SELECT COUNT(*) FROM product_discount_tiers WHERE organization_id=? AND market_id=? AND status='active'",[$orgId,$marketId]);$metrics['tier_prices']=$scalar("SELECT COUNT(*) FROM product_tier_prices tp JOIN product_price_versions pv ON pv.id=tp.price_version_id WHERE pv.organization_id=? AND pv.effective_from=?",[$orgId,PRODUCT_STEP11_EFFECTIVE_DATE]);$metrics['docs']=$scalar("SELECT COUNT(*) FROM product_source_documents WHERE organization_id=? AND market_id=? AND effective_date=? AND status='active'",[$orgId,$marketId,PRODUCT_STEP11_EFFECTIVE_DATE]);$metrics['rules']=$scalar("SELECT COUNT(*) FROM product_delivery_rules WHERE organization_id=? AND market_id=? AND status='active'",[$orgId,$marketId]);$metrics['images']=$scalar("SELECT COUNT(DISTINCT pi.product_id) FROM product_images pi JOIN products p ON p.id=pi.product_id WHERE p.organization_id=?",[$orgId]);$metrics['verified_images']=$scalar("SELECT COUNT(DISTINCT pi.product_id) FROM product_images pi JOIN products p ON p.id=pi.product_id WHERE p.organization_id=? AND pi.verification_status='verified'",[$orgId]);$metrics['duplicate_sku']=$scalar("SELECT COUNT(*) FROM (SELECT sku FROM products WHERE organization_id=? GROUP BY sku HAVING COUNT(*)>1) x",[$orgId]);$metrics['quotes']=$scalar("SELECT COUNT(*) FROM product_quotes WHERE organization_id=?",[$orgId]);
