$requiredFiles=['product_catalog.php','product_detail.php','product_data_center.php','product_images.php','product_price_history.php','product_compare.php','product_order_builder.php','product_quotes.php','product_favorites.php','product_import_center.php','product_seed.php','product_placeholder.php'];$filesOk=true;foreach($requiredFiles as $f)if(!is_file(__DIR__.'/'.$f)){$filesOk=false;break;}
